import asyncio
import collections
import json
import math

import geometry
import net
import settings
from netlog import log

# Airports this radar displays (basemap_data.py, generated by make_basemap.py):
# optional and per-location, same as radar.py's own import of it -- catch
# everything, not just ImportError, so a compile / MemoryError in the
# generated module can't take route lookups down with it.
try:
    import basemap_data
except Exception:  # noqa: BLE001
    basemap_data = None

ADSBLOL_HOST = "api.adsb.lol"
ADSBDB_HOST = "api.adsbdb.com"

EARTH_RADIUS_KM = 6371.0
NEAR_AIRPORT_KM = 30  # SFO approaches often overfly the field before a near-180°
                      # turn to land; within this range of a displayed airport,
                      # _plausible() stops requiring the track to point at it.

# callsign -> (origin, dest) | None (unknown) | "" (pending) | absent (never requested)
#
# An LRU, capped at _CACHE_MAX: one list-view cycle touches ~30 callsigns and
# the old plain dict grew one entry per callsign ever seen (DATA_TODOS.md #3).
# Reads count as a use (_cache_get / get), so the currently visible rows stay
# hot; a resolved (o, d) that falls cold is dropped and re-fetched later at no
# correctness cost. Always go through _cache_set / _cache_get, never index
# _cache directly, or the ordering and the cap stop being maintained.
_cache = collections.OrderedDict()
_CACHE_MAX = 64

# callsign -> lookups spent so far, while still unresolved. adsb.lol's route
# data is routinely stale or missing for the first ~2 min of a flight and then
# fills in with the real rotation, so a None result isn't final: request() will
# re-fetch it, up to _MAX_TRIES times. The selection is re-request()ed once per
# feed fetch (ui.on_feed_update -> set_selected), so this is ~_MAX_TRIES feed
# cycles. Cleared once a route resolves; a plausible hit is never re-checked.
# Pruned alongside _cache when an entry is evicted.
_tries = {}
_MAX_TRIES = 4


def _cache_set(cs, value):
    """Write cs -> value, mark it most-recently-used, and evict the oldest
    entries (and their _tries) if the cache is over _CACHE_MAX."""
    _cache[cs] = value
    _cache.move_to_end(cs)
    while len(_cache) > _CACHE_MAX:
        old, _ = _cache.popitem(last=False)
        _tries.pop(old, None)


def _cache_get(cs, default=None):
    """Read cs, counting the read as a use so a still-wanted route isn't the
    next thing evicted. A miss doesn't touch the cache."""
    if cs in _cache:
        _cache.move_to_end(cs)
        return _cache[cs]
    return default


def is_hex_id(cs):
    return len(cs) == 6 and all(c in "0123456789ABCDEF" for c in cs.upper())


# --- great-circle plausibility check ----------------------------------
#
# Is the aircraft's current position/track consistent with being somewhere
# on the leg from airport A to airport B? Standard cross-track/along-track
# distance from the great-circle line (movable-type.co.uk/scripts/latlong),
# plus a track check position alone can't do: "just departed A" and
# "arriving at A" put the plane in the same place, only its heading tells
# them apart. This is the one and only copy of that algorithm: prototyped in
# prestoradar/dev/route_check.py (see that file's docstring for how it was
# arrived at, including a bug found in adsb.lol's own "plausible" flag --
# always true -- that ruled out just trusting it as-is), but route_check.py
# now calls _leg_fit()/_leg_ok() here rather than keeping its own copy, so a
# fix made for one caller (e.g. the near-airport heading bypass below) can't
# quietly go missing from the other.

def _gc_distance_km(lat1, lon1, lat2, lon2):
    lat1, lon1, lat2, lon2 = (math.radians(x) for x in (lat1, lon1, lat2, lon2))
    a = (math.sin((lat2 - lat1) / 2) ** 2
         + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2)
    return 2 * EARTH_RADIUS_KM * math.asin(math.sqrt(a))


def _bearing_deg(lat1, lon1, lat2, lon2):
    lat1, lon1, lat2, lon2 = (math.radians(x) for x in (lat1, lon1, lat2, lon2))
    y = math.sin(lon2 - lon1) * math.cos(lat2)
    x = math.cos(lat1) * math.sin(lat2) - math.sin(lat1) * math.cos(lat2) * math.cos(lon2 - lon1)
    return math.degrees(math.atan2(y, x)) % 360


def _angle_diff(a, b):
    d = abs(a - b) % 360
    return d if d <= 180 else 360 - d


def _near_displayed_airport(lat, lon):
    """True if (lat, lon) is within NEAR_AIRPORT_KM of one of the airports
    this radar displays (basemap_data.AIRPORTS -- projected east/north km
    from the centre, same frame as geometry.project()). False, never True,
    if no basemap loaded -- see the import above. Used to waive _plausible()'s
    heading check: an aircraft can be legitimately right on top of its
    destination while pointed the wrong way, mid-turn."""
    if basemap_data is None:
        return False
    e, n = geometry.project(lat, lon)
    return any(math.sqrt((e - ax) ** 2 + (n - ay) ** 2) <= NEAR_AIRPORT_KM
               for _code, ax, ay in basemap_data.AIRPORTS)


def _leg_fit(pos_lat, pos_lon, track, a_lat, a_lon, b_lat, b_lon):
    """Raw geometry: how well does (pos_lat, pos_lon), heading `track`
    (degrees, or None), fit as being somewhere on the great-circle leg from
    A to B? No opinion on near_airport -- see _leg_ok(), which turns this
    into a plausibility verdict, and route_check.py, the desktop harness
    that reports these numbers for legs it rejects too."""
    dist_ab = _gc_distance_km(a_lat, a_lon, b_lat, b_lon)
    threshold = max(50 * 1.852, 0.20 * dist_ab)  # 50 nm, or 20% of the leg

    d13 = _gc_distance_km(a_lat, a_lon, pos_lat, pos_lon) / EARTH_RADIUS_KM
    theta13 = math.radians(_bearing_deg(a_lat, a_lon, pos_lat, pos_lon))
    theta12 = math.radians(_bearing_deg(a_lat, a_lon, b_lat, b_lon))
    xt = max(-1.0, min(1.0, math.sin(d13) * math.sin(theta13 - theta12)))
    cross_track = math.asin(xt) * EARTH_RADIUS_KM
    c = max(-1.0, min(1.0, math.cos(d13) / math.cos(cross_track / EARTH_RADIUS_KM)))
    along_track = math.acos(c) * EARTH_RADIUS_KM
    if _angle_diff(math.degrees(theta13), math.degrees(theta12)) > 90:
        along_track = -along_track

    on_the_line = abs(cross_track) <= threshold and -threshold <= along_track <= dist_ab + threshold
    track_diff = None
    if track is not None:
        track_diff = _angle_diff(track, _bearing_deg(pos_lat, pos_lon, b_lat, b_lon))
    return {"dist_ab_km": dist_ab, "cross_track_km": cross_track,
            "along_track_km": along_track, "on_the_line": on_the_line,
            "track_ok": track_diff is None or track_diff <= 90,
            "track_diff_deg": track_diff}


def _leg_ok(fit, near_airport=False):
    """Does a _leg_fit() result count as plausible? `near_airport` (see
    _near_displayed_airport()) waives the heading check -- an aircraft can be
    legitimately right on top of its destination while pointed the wrong
    way, mid-turn."""
    return fit["on_the_line"] and (fit["track_ok"] or near_airport)


def _plausible(pos_lat, pos_lon, track, a_lat, a_lon, b_lat, b_lon, near_airport=False):
    fit = _leg_fit(pos_lat, pos_lon, track, a_lat, a_lon, b_lat, b_lon)
    return _leg_ok(fit, near_airport)


# --- route sources -------------------------------------------------------

async def _get_json(host, path):
    """GET and parse a JSON object, or None on any failure -- unreachable
    host, non-200, an unparseable body, or a bare `null` (adsb.lol's
    airport endpoint has been seen to answer 200 with `null` when its
    backend is unhappy). Returning None rather than raising lets one flaky
    source fall through to the next in the same _fetch() pass."""
    try:
        status, body = await net.http_get(host, path, settings.USER_AGENT)
        if status != 200:
            return None
        data = json.loads(body)
    except Exception as e:  # noqa: BLE001
        log("route source error:", host, path, repr(e))
        return None
    return data if isinstance(data, dict) else None


async def _fetch_adsbdb(callsign):
    """One (code, lat, lon, code, lat, lon) leg, or None if adsbdb has
    nothing (or something without coordinates)."""
    data = await _get_json(ADSBDB_HOST, "/v0/callsign/" + callsign)
    resp = (data or {}).get("response")
    fr = resp.get("flightroute") if isinstance(resp, dict) else None
    if not fr:
        return None
    o, d = fr.get("origin") or {}, fr.get("destination") or {}
    if o.get("latitude") is None or d.get("latitude") is None:
        return None
    a_code = o.get("iata_code") or o.get("icao_code") or "?"
    b_code = d.get("iata_code") or d.get("icao_code") or "?"
    return (a_code, o["latitude"], o["longitude"], b_code, d["latitude"], d["longitude"])


async def _fetch_adsblol_legs(callsign, lat, lon):
    """One leg tuple per leg of the plane's whole rotation, in order --
    unlike adsbdb, which only ever has one remembered leg. lat/lon only feed
    adsb.lol's own (unusable, see module docstring) `plausible` field; this
    ignores it and scores every leg itself."""
    data = await _get_json(
        ADSBLOL_HOST, "/api/0/route/%s/%s/%s" % (callsign, lat, lon))
    airports = (data or {}).get("_airports") or []
    legs = []
    for a, b in zip(airports, airports[1:]):
        if a.get("lat") is None or b.get("lat") is None:
            continue
        a_code = a.get("iata") or a.get("icao") or "?"
        b_code = b.get("iata") or b.get("icao") or "?"
        legs.append((a_code, a["lat"], a["lon"], b_code, b["lat"], b["lon"]))
    return legs


async def _fetch(callsign, lat, lon, track):
    """adsbdb first -- one request, same cost as before. Only escalate to
    adsb.lol's full-rotation lookup (a second request) if adsbdb has
    nothing, or what it has doesn't fit the plane's actual position and
    heading -- e.g. a multi-leg rotation where adsbdb only knows a
    different remembered leg."""
    route = None
    near_airport = _near_displayed_airport(lat, lon)
    try:
        leg = await _fetch_adsbdb(callsign)
        if leg and _plausible(lat, lon, track, leg[1], leg[2], leg[4], leg[5], near_airport):
            route = (leg[0], leg[3])
        else:
            for leg in await _fetch_adsblol_legs(callsign, lat, lon):
                if _plausible(lat, lon, track, leg[1], leg[2], leg[4], leg[5], near_airport):
                    route = (leg[0], leg[3])
                    break
    except Exception as e:  # noqa: BLE001
        log("route lookup failed:", callsign, repr(e))
        route = None
    _cache_set(callsign, route)
    if route is not None:
        _tries.pop(callsign, None)
    log("route", callsign, "->", route, "(try", _tries.get(callsign, 0), "of", _MAX_TRIES, ")")


def _route_callsign(p):
    """p's callsign if it's a real one to look up, else None -- feed.py falls
    back to the ICAO hex id when a plane isn't broadcasting a callsign, so
    p.callsign == p.hex is never a route. (Can't just test is_hex_id(cs): a
    real callsign like ACA568 is six characters that all happen to be hex
    digits.)"""
    cs = (p.callsign or "").strip()
    if not cs or cs.lower() == (p.hex or "").lower():
        return None
    return cs


def _eligible(cs):
    """True if cs is worth a (re)fetch: not already resolved, not currently
    in flight, and not a None result that's used up its _MAX_TRIES."""
    cached = _cache_get(cs, "absent")
    if cached == "" or isinstance(cached, tuple):
        return False
    if cached is None and _tries.get(cs, 0) >= _MAX_TRIES:
        return False
    return True


def _mark_launching(cs):
    """Move cs to the pending state and count the try. Paired with an
    immediate _fetch() launch by both request() and the batch queue."""
    _cache_set(cs, "")
    _tries[cs] = _tries.get(cs, 0) + 1


def request(p):
    """Kick off a route lookup for plane.Plane p if one isn't already resolved
    or in flight. A no-op when the plane isn't broadcasting a real callsign.
    Callers can pass a plane straight through even before its callsign is
    known to be real.

    Re-callable: a still-unresolved route (cached None) is re-fetched, with
    p's current position/heading, until it resolves or _MAX_TRIES is hit.
    Fires immediately and unthrottled -- it's the single-aircraft tap path.
    Batch callers wanting routes for a whole screen use enqueue_many()."""
    cs = _route_callsign(p)
    if cs is None or not _eligible(cs):
        return
    _mark_launching(cs)
    lat, lon = geometry.unproject(p.e, p.n)
    asyncio.create_task(_fetch(cs, lat, lon, p.heading))


# --- batch use (nearby.py) --------------------------------------------
#
# A list view wants routes for every visible aircraft (~30) at once, but
# adsb.lol's public endpoints ask for ~1 request/second. Pacing that is the
# caller's job, not this module's: nearby.py runs a fetchqueue.Queue (the
# same generic, paced queue traces.py's backfill uses) and calls the two
# building blocks below from its enqueue and process_one. request() above
# stays the immediate, unthrottled single-tap path -- unrelated to this.

def eligible(p):
    """True if p has a real callsign that's worth a route (re)fetch right
    now -- not already resolved, not currently in flight, and not out of
    retries. What a batch caller checks before enqueueing."""
    cs = _route_callsign(p)
    return cs is not None and _eligible(cs)


async def fetch_for(p):
    """Fetch p's route now, awaited -- unlike request(), which fires an
    unthrottled background task. A caller pacing its own queue awaits this
    once per drained entry. No-op if p is no longer eligible (resolved by
    another path since it was enqueued, or never had a real callsign)."""
    if not eligible(p):
        return
    cs = _route_callsign(p)
    _mark_launching(cs)
    lat, lon = geometry.unproject(p.e, p.n)
    await _fetch(cs, lat, lon, p.heading)


def get(callsign):
    """Current cached state for callsign: an (origin, dest) tuple, None
    (looked up, unknown), "" (pending), or "absent" (never requested).
    Counts as a use -- polling get() for a visible row keeps it hot."""
    return _cache_get(callsign, "absent")


def retrying(callsign):
    """True while a None (unknown) result still has request() re-fetches
    left -- i.e. "keep showing 'looking...', not 'unknown' yet"."""
    return _cache_get(callsign) is None and _tries.get(callsign, 0) < _MAX_TRIES
